/** Provided -- the event types. Do not edit. */
interface LedgerEvent {
}

/** Provided -- money arriving, in whole cents. Do not edit. */
record Deposited(long cents) implements LedgerEvent {
}

/** Provided -- money the customer takes out, in whole cents. Do not edit. */
