}

/** Provided -- a fee the bank takes, in whole cents. Do not edit. */
record FeeCharged(long cents) implements LedgerEvent {
}

/** Provided -- the account is frozen. Do not edit. */
record Frozen() implements LedgerEvent {
}

/** Provided -- the account is unfrozen. Do not edit. */
record Unfrozen() implements LedgerEvent {
}

/** Provided -- the state an event log replays to. Do not edit. */
record AccountState(long balanceCents, boolean frozen, int applied, int rejected) {
}

/**
 * TASK: Implement event sourcing -- rebuild an account's state by replaying its event log.
 *
 * There is no stored balance anywhere; the only truth is the ordered list of events, and
 * replay folds them into an AccountState. Start from balance 0, not frozen, 0 applied,
 * 0 rejected. Then, for each event IN ORDER, either APPLY it (change the state, and add 1
 * to applied) or REJECT it (leave the balance and frozen flag alone, and add 1 to rejected).
 *
 * The rules, in full:
 *  - Deposited: apply when cents > 0 and the account is not frozen; add cents to the balance.
 *  - Withdrew: apply when cents > 0, the account is not frozen, AND cents <= the current
 *    balance; subtract cents. A withdrawal larger than the balance is rejected, never
 *    partially applied.
 *  - FeeCharged: apply when cents > 0 and the account is not frozen; subtract cents. Unlike
 *    a withdrawal, a fee is allowed to push the balance NEGATIVE.
 *  - Frozen: apply only when the account is not already frozen; then it becomes frozen.
 *    Freezing an already frozen account is rejected.
 *  - Unfrozen: apply only when the account IS frozen; then it becomes unfrozen. Unfreezing
 *    an already open account is rejected.
 *  - Any event with cents <= 0 is rejected.
 *  - A null element inside the list is rejected (do not throw).
 *  - A null list, or an empty one, replays to the starting state: AccountState(0, false, 0, 0).
 *
 * Example: replay(List.of(new Deposited(500), new Withdrew(900), new FeeCharged(600)))
 *          -> AccountState(-100, false, 2, 1)
 *          The 900 withdrawal is rejected (balance was only 500) but the 600 fee applies
 *          and takes the balance below zero.
 */
public class LedgerReplayer {

    public static AccountState replay(List<LedgerEvent> events) {
        // TODO: fold the events into a state, counting applied and rejected events
        return new AccountState(0, false, 0, 0);
    }
