import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class LedgerReplayerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String show(List<LedgerEvent> events) {
        try {
            AccountState state = LedgerReplayer.replay(events);
            if (state == null) {
                return "null";
            }
            return state.balanceCents() + "/" + state.frozen() + "/" + state.applied()
                    + "/" + state.rejected();
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("plain deposits", "800/false/2/0",
                show(Arrays.asList(new Deposited(500), new Deposited(300))));
        check("overdraft withdrawal rejected, fee still applies", "-100/false/2/1",
                show(Arrays.asList(new Deposited(500), new Withdrew(900), new FeeCharged(600))));
        check("withdrawal of the exact balance is allowed", "0/false/2/0",
                show(Arrays.asList(new Deposited(250), new Withdrew(250))));
        check("frozen account rejects money movement", "500/true/2/3",
                show(Arrays.asList(new Deposited(500), new Frozen(), new Deposited(100),
                        new Withdrew(100), new FeeCharged(50))));
        check("double freeze rejected, unfreeze restores service", "700/false/3/1",
                show(Arrays.asList(new Frozen(), new Frozen(), new Unfrozen(), new Deposited(700))));
        check("unfreezing an open account is rejected", "0/false/0/1",
                show(Arrays.asList(new Unfrozen())));
        check("zero and negative amounts rejected", "10/false/1/3",
                show(Arrays.asList(new Deposited(0), new Deposited(-5), new FeeCharged(0),
                        new Deposited(10))));
        List<LedgerEvent> withNull = new ArrayList<>();
        withNull.add(new Deposited(20));
        withNull.add(null);
        check("null event rejected, not thrown", "20/false/1/1", show(withNull));
        check("empty log", "0/false/0/0", show(new ArrayList<LedgerEvent>()));
        check("null log", "0/false/0/0", show(null));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

