import java.util.List;

/** Provided -- the event types. Do not edit. */
interface LedgerEvent {
}

/** Provided -- money arriving, in whole cents. Do not edit. */
record Deposited(long cents) implements LedgerEvent {
}

/** Provided -- money the customer takes out, in whole cents. Do not edit. */
record Withdrew(long cents) implements LedgerEvent {
}

/** Provided -- a fee the bank takes, in whole cents. Do not edit. */
record FeeCharged(long cents) implements LedgerEvent {
}

/** Provided -- the account is frozen. Do not edit. */
record Frozen() implements LedgerEvent {
}

/** Provided -- the account is unfrozen. Do not edit. */
record Unfrozen() implements LedgerEvent {
}

/** Provided -- the state an event log replays to. Do not edit. */
record AccountState(long balanceCents, boolean frozen, int applied, int rejected) {
}

public class LedgerReplayer {

    public static AccountState replay(List<LedgerEvent> events) {
        long balance = 0;
        boolean frozen = false;
        int applied = 0;
        int rejected = 0;
        if (events == null) {
            return new AccountState(balance, frozen, applied, rejected);
        }
        for (LedgerEvent event : events) {
            boolean ok = false;
            if (event instanceof Deposited deposit) {
                if (deposit.cents() > 0 && !frozen) {
                    balance += deposit.cents();
                    ok = true;
                }
            } else if (event instanceof Withdrew withdrawal) {
                if (withdrawal.cents() > 0 && !frozen && withdrawal.cents() <= balance) {
                    balance -= withdrawal.cents();
                    ok = true;
                }
            } else if (event instanceof FeeCharged fee) {
                if (fee.cents() > 0 && !frozen) {
                    balance -= fee.cents();
                    ok = true;
                }
            } else if (event instanceof Frozen) {
                if (!frozen) {
                    frozen = true;
                    ok = true;
                }
            } else if (event instanceof Unfrozen) {
                if (frozen) {
                    frozen = false;
                    ok = true;
                }
            }
            if (ok) {
                applied++;
            } else {
                rejected++;
            }
        }
        return new AccountState(balance, frozen, applied, rejected);
    }
}
